numbers = [21, 34, 43, 57, 66, 78]   # must be sorted
target = 78

def binary_search():
    low, high = 0, len(numbers) - 1
    step = 0
    while low <= high:
        mid = (low + high) // 2
        step += 1
        print("Step", step, ": middle =", numbers[mid])
        if numbers[mid] == target:
            return mid, step
        elif target > numbers[mid]:
            low = mid + 1                # search the right half
        else:
            high = mid - 1               # search the left half
    return -1, step

position, steps = binary_search()
if position == -1:
    print(target, "is not in the list; checks:", steps)
else:
    print(target, "found at position", position, "in", steps, "checks")
